  def pixel_icon(name, size: 16, css_class: "")
    svg = PIXEL_ICONS[name.to_sym]
    return "" unless svg

    tag.span(
      svg.html_safe,
      class: "pixel-icon #{css_class}".strip,
      style: "width:#{size}px;height:#{size}px"
    )
  end
